import json

def summarize_content(content):
    out = []
    if isinstance(content, str):
        return content[:2000]
    if isinstance(content, list):
        for c in content:
            if not isinstance(c, dict):
                out.append(str(c)[:500])
                continue
            t = c.get('type')
            if t == 'text':
                out.append('[TEXT] ' + c.get('text','')[:2000])
            elif t == 'tool_use':
                inp = json.dumps(c.get('input',{}))[:800]
                out.append(f'[TOOL_USE {c.get(\"name\")}] {inp}')
            elif t == 'tool_result':
                cont = c.get('content')
                if isinstance(cont, list):
                    s = ' '.join(x.get('text','')[:500] for x in cont if isinstance(x,dict))
                else:
                    s = str(cont)[:500]
                out.append(f'[TOOL_RESULT] {s}')
            else:
                out.append(f'[{t}] ' + json.dumps(c)[:300])
    return '\n'.join(out)

with open('log.jsonl') as f:
    lines = f.readlines()

with open('readable.txt', 'w') as out:
    for i, line in enumerate(lines):
        try:
            d = json.loads(line)
        except:
            continue
        t = d.get('type')
        ts = d.get('timestamp')
        if t in ('user','assistant'):
            msg = d.get('message', {})
            role = msg.get('role')
            content = msg.get('content')
            out.write(f'=== [{i}] {ts} {role} ===\n')
            out.write(summarize_content(content))
            out.write('\n\n')
print('done', len(lines))
"
