import json

def summarize_content(content):
    out = []
    if isinstance(content, str):
        return content[:3000]
    if isinstance(content, list):
        for c in content:
            if not isinstance(c, dict):
                out.append(str(c)[:500])
                continue
            t = c.get('type')
            if t == 'text':
                out.append('[TEXT] ' + c.get('text','')[:3000])
            elif t == 'tool_use':
                inp = json.dumps(c.get('input',{}))[:1000]
                out.append(f'[TOOL_USE {c.get(\"name\")}] {inp}')
            elif t == 'tool_result':
                cont = c.get('content')
                if isinstance(cont, list):
                    s = ' '.join(x.get('text','')[:800] for x in cont if isinstance(x,dict))
                else:
                    s = str(cont)[:800]
                out.append(f'[TOOL_RESULT] {s}')
            else:
                out.append(f'[{t}] ' + json.dumps(c)[:300])
    return '\n'.join(out)

