import json
out=[]
with open('log_clean.jsonl') as f:
    for i, line in enumerate(f, 1):
        line=line.strip()
        if not line: continue
        try:
            d = json.loads(line)
        except Exception as e:
            out.append(f"{i}: PARSE_ERROR {e}")
            continue
        t = d.get('type')
        ts = d.get('timestamp','')
        if t == 'user':
            msg = d.get('message',{})
            content = msg.get('content')
            if isinstance(content, str):
                out.append(f"{i} [{ts}] USER: {content[:400]}")
            elif isinstance(content, list):
                for c in content:
                    if c.get('type') == 'tool_result':
                        cc = c.get('content')
                        if isinstance(cc, list):
                            s = ' '.join(x.get('text','')[:250] for x in cc if isinstance(x,dict))
                        else:
                            s = str(cc)[:250]
                        out.append(f"{i} [{ts}] TOOL_RESULT: {s}")
                    elif c.get('type')=='text':
                        out.append(f"{i} [{ts}] USER_TEXT: {c.get('text','')[:400]}")
        elif t == 'assistant':
            msg = d.get('message',{})
            content = msg.get('content',[])
            for c in content:
                if c.get('type') == 'text':
                    out.append(f"{i} [{ts}] ASSISTANT: {c.get('text','')[:500]}")
                elif c.get('type') == 'tool_use':
                    out.append(f"{i} [{ts}] TOOL_USE: {c.get('name')} {json.dumps(c.get('input',{}))[:350]}")
        elif t == 'attachment':
            a = d.get('attachment',{})
            at = a.get('type')
            if at not in ('total_tokens_reminder','deferred_tools_delta','agent_listing_delta','mcp_instructions_delta','skill_listing','auto_mode','command_permissions','task_reminder'):
                out.append(f"{i} [{ts}] ATTACH:{at} {json.dumps(a)[:350]}")
        elif t in ('queue-operation','last-prompt','atis-latch'):
            pass
        else:
            out.append(f"{i} [{ts}] TYPE={t}")
with open('summary2.txt','w') as f:
    f.write('\n'.join(out))
print(len(out))
EOF
